const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const furnaceCreek = ee.Geometry.Point([-116.8679, 36.4633]); // Furnace Creek Visitor's Center
  const startDate = '2013-06-30T00:00:00';
  const endDate = '2013-06-30T23:59:59'; // Entire day of June 30, 2013

  // 2. Data Acquisition & Check
  let temperatureCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(furnaceCreek)
    .select('temperature_2m');

  const initialSize = await temperatureCollection.size().getInfo();

  if (initialSize === 0) {
    console.log("No ERA5-Land hourly data found for June 30, 2013, at Furnace Creek.");
    console.log("C1");
    return;
  }

  // Function to convert Kelvin to Celsius
  const toCelsius = (image) => image.subtract(273.15).rename('temperature_celsius');

  // Apply conversion to the collection
  temperatureCollection = temperatureCollection.map(toCelsius);

  // Find the maximum temperature over the day
  const maxTemperatureImage = temperatureCollection.max();

  // 3. Processing (Calculate pixel count, though for a point and ERA5-Land, it's typically 1)
  const scale = 11132; // Approx. 0.1 degree resolution for ERA5-Land (11.132 km at equator)

  const regionResult = await maxTemperatureImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: furnaceCreek,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const maxTempCelsius = regionResult ? regionResult['temperature_celsius'] : null;

  // Validate the pixel count for the region (should be 1 for a point if data exists)
  const pixelCount = await maxTemperatureImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: furnaceCreek,
    scale: scale,
    maxPixels: 1e9
  }).get('temperature_celsius').getInfo(); // Use the band name after conversion and selection

  if (pixelCount === 0) {
    console.log("No valid pixels found after processing for max temperature.");
    console.log("C2");
    return;
  }

  // 4. Calculation and Validation
  if (maxTempCelsius === null || isNaN(maxTempCelsius)) {
    console.log("Calculation failed: Maximum temperature could not be determined.");
    console.log("C3");
    return;
  }

  const threshold = 50; // degrees Celsius
  const didReachThreshold = maxTempCelsius > threshold;

  // 5. Validation & Final Answer
  console.log(`ERA5-Land images for June 30, 2013: ${initialSize}`);
  console.log(`Valid pixels at Furnace Creek: ${pixelCount}`);
  console.log(`Max air temperature (2m) on June 30, 2013, at Furnace Creek: ${maxTempCelsius.toFixed(2)} °C`);

  if (didReachThreshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
